std::string text(YNXAIMobileSpanV6 value,size_t cap,bool empty=false){if(value.bytes>cap||(!value.data&&value.bytes)||(!empty&&!value.bytes))throw invalid;std::string result(value.bytes?reinterpret_cast<const char*>(value.data):"",value.bytes);if(result.find('\0')!=std::string::npos)throw invalid;return result;}
