bool current(const std::shared_ptr<Context>&c)noexcept{if(!c||c->actor!=std::this_thread::get_id()||c->closed||c->released||c->cancelled.load()||!c->life||!c->life->load()||!c->ready)return false;auto wall=wallMS(),mono=monoMS();if(c->expiresAtMs<=c->wall0||wall<c->lastWall||wall<c->wall0||wall>=c->expiresAtMs||mono<c->mono0||mono-c->mono0>=c->expiresAtMs-c->wall0)return false;c->lastWall=wall;return true;}
