bool isOriginalContext(YNXAIMobileSDKContext*c,YNXAuthAIMobileOwnerV6*s,uint64_t runtime)noexcept{try{auto value=context(c);return value&&value->source==s&&value->runtime==runtime&&!value->released;}catch(...){return false;}}
